import {dimensions} from './grid.mjs';
import {position,terrainHeight} from './geo.mjs';
import {sampleTerrain,noise} from './terrain.mjs';
import {waterMeshFor} from './terrain-water.mjs';
const cache=new WeakMap();
import {terrainSurvey,terrainColor,terrainAtlas} from './terrain-style.mjs';
function colorAt(city,x,y,h,snow){const {width,height}=dimensions(city),id=Math.min(height-1,Math.max(0,Math.floor(y)))*width+Math.min(width-1,Math.max(0,Math.floor(x)));return terrainColor(city,id,{snow});}
function meshFor(city,snow){const {width,height,cellSize}=dimensions(city),n=(width+1)*(height+1),p=new Float32Array(n*3),normals=new Float32Array(n*3),colors=new Float32Array(n*3),uv=new Float32Array(n*2),indices=new Uint32Array(width*height*6);let k=0;const survey=terrainSurvey(city);
 for(let y=0;y<=height;y++)for(let x=0;x<=width;x++){const i=y*(width+1)+x,ground=terrainHeight(city,x,y),tile=city.tiles[Math.min(height-1,y)*width+Math.min(width-1,x)],h=ground===0&&tile.terrain==='water'?-12-Math.min(36,survey.coast[tile.id]*3):ground;p.set([(x-width/2)*cellSize,(y-height/2)*cellSize,h],i*3);const sx=(terrainHeight(city,x+.5,y)-terrainHeight(city,x-.5,y))/cellSize,sy=(terrainHeight(city,x,y+.5)-terrainHeight(city,x,y-.5))/cellSize,len=Math.hypot(sx,sy,1);normals.set([-sx/len,-sy/len,1/len],i*3);colors.set(colorAt(city,x,y,h,snow).map(v=>v/255),i*3);uv.set([x/width,y/height],i*2);if(x<width&&y<height){const a=i,b=i+1,c=i+width+1,d=c+1;indices.set([a,b,d,a,d,c],k);k+=6;}}
 return {attributes:{positions:{value:p,size:3},normals:{value:normals,size:3},colors:{value:colors,size:3},texCoords:{value:uv,size:2}},indices:{value:indices,size:1}};
}
function contextMesh(city,snow){const {width,height,cellSize}=dimensions(city),p=[],n=[],c=[],uv=[],step=8;
 const sample=(x,y)=>{const outside=Math.max(0,-x,x-width,-y,y-height),t=sampleTerrain(city.preset,x/width,y/height,city.seed,city.terrainConfig),edge=terrainHeight(city,Math.max(0,Math.min(width,x)),Math.max(0,Math.min(height,y))),blend=Math.min(1,outside/24),h=edge*(1-blend)+t.elevation*6*blend;return {h,color:t.terrain==='water'&&blend>.4?[28,76,94]:colorAt(city,Math.max(0,Math.min(width,x)),Math.max(0,Math.min(height,y)),h,snow)};};
 for(let y=-96;y<height+96;y+=step)for(let x=-128;x<width+128;x+=step){if(x>=0&&x<width&&y>=0&&y<height)continue;const points=[[x,y],[x+step,y],[x+step,y+step],[x,y],[x+step,y+step],[x,y+step]];for(const [a,b]of points){const v=sample(a,b);p.push((a-width/2)*cellSize,(b-height/2)*cellSize,v.h);const sx=(sample(a+1,b).h-sample(a-1,b).h)/(cellSize*2),sy=(sample(a,b+1).h-sample(a,b-1).h)/(cellSize*2),len=Math.hypot(sx,sy,1);n.push(-sx/len,-sy/len,1/len);c.push(...v.color.map(q=>q/255));uv.push(0,0);}}
 // Close the seam between the one-parcel region mesh and the coarser horizon.
 // Both edges keep their original heights; short vertical faces hide T-junction gaps.
 const stitch=(horizontal,fixed,length)=>{for(let i=0;i<length;i++){const at=v=>horizontal?[v,fixed]:[fixed,v],coarse=v=>{const lo=Math.floor(v/step)*step,hi=Math.min(length,lo+step),a=at(lo),b=at(hi),t=hi===lo?0:(v-lo)/(hi-lo);return terrainHeight(city,...a)*(1-t)+terrainHeight(city,...b)*t;},a=at(i),b=at(i+1),ha=terrainHeight(city,...a),hb=terrainHeight(city,...b),ca=coarse(i),cb=coarse(i+1);if(Math.abs(ha-ca)+Math.abs(hb-cb)<.01)continue;for(const [x,y,z] of [[...a,ha],[...b,hb],[...b,cb],[...a,ha],[...b,cb],[...a,ca]]){p.push((x-width/2)*cellSize,(y-height/2)*cellSize,z);n.push(horizontal?0:(fixed?1:-1),horizontal?(fixed?1:-1):0,0);c.push(...colorAt(city,x,y,z,snow).map(v=>v/255));uv.push(0,0);}}};
 stitch(true,0,width);stitch(true,height,width);stitch(false,0,height);stitch(false,width,height);
 return {attributes:{positions:{value:new Float32Array(p),size:3},normals:{value:new Float32Array(n),size:3},colors:{value:new Float32Array(c),size:3},texCoords:{value:new Float32Array(uv),size:2}}};
}
export function terrainLayers(city,{underground=false,cutDepth=45,snow=false,onClick}={}){const {deck}=window,{width,height}=dimensions(city),key=`${city.terrainRevision||0}:${snow}`;let entry=cache.get(city);if(entry?.key!==key){entry={key,mesh:meshFor(city,snow),context:contextMesh(city,snow),water:waterMeshFor(city),anchors:new Map(),grid:[]};for(let y=0;y<=height;y+=2)entry.grid.push({path:Array.from({length:width+1},(_,x)=>position(x,y,terrainHeight(city,x,y)+.3,city))});for(let x=0;x<=width;x+=2)entry.grid.push({path:Array.from({length:height+1},(_,y)=>position(x,y,terrainHeight(city,x,y)+.3,city))});cache.set(city,entry);}
 const depth=underground?-cutDepth:0;if(!entry.anchors.has(depth))entry.anchors.set(depth,[{position:position(width/2,height/2,depth,city)}]);const anchor=entry.anchors.get(depth);
 const layers=[new deck.SimpleMeshLayer({id:'surrounding-terrain',data:anchor,mesh:entry.context,_useMeshColors:true,getPosition:d=>d.position,getColor:underground?[48,67,74]:[255,255,255],material:{ambient:.65,diffuse:.7},pickable:false}),new deck.SimpleMeshLayer({id:'regional-terrain',data:anchor,mesh:entry.mesh,_useMeshColors:false,texture:{data:terrainAtlas(city,snow),mipmaps:false},textureParameters:{10241:9729,10240:9729,10242:33071,10243:33071},getPosition:d=>d.position,getColor:underground?[48,67,74]:[255,255,255],material:{ambient:.55,diffuse:.9,shininess:5},pickable:true,onClick})];
 if(underground)layers.push(new deck.PathLayer({id:'surface-survey-grid',data:entry.grid,getPath:d=>d.path,getColor:[156,206,203,48],getWidth:1,widthUnits:'pixels',parameters:{depthMask:false},pickable:false}));
 else layers.push(new deck.SimpleMeshLayer({id:'regional-water',parameters:{polygonOffsetFill:true,polygonOffset:[-1,-4]},data:anchor,mesh:entry.water,_useMeshColors:true,getPosition:d=>d.position,getColor:[255,255,255],material:{ambient:.55,diffuse:.55,shininess:90,specularColor:[105,138,153]},pickable:true,onClick}));
 // A much larger flat horizon hides the board-like plinth without claiming extra buildable parcels.
 const edge=[[-width,-height],[width*2,-height],[width*2,height*2],[-width,height*2]].map(([x,y])=>position(x,y,-70-cutDepth,city));
 layers.unshift(new deck.PolygonLayer({id:'regional-horizon',data:[edge],getPolygon:d=>d,getFillColor:[26,57,78],stroked:false,material:false}));return layers;
}
